-- 复制 会计场景，会计元素，场景分支配置（理财账），场景科目关系（理财账）
delete from BOK_TABLELIST where BOOKSET_ID in ('00000000000000000001','00000000000000000003','00000000000000000004');
select B.BOOKSET_ID, A.TABLE_ID, A.TABLE_NAME, A.REMARK, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME 
from BOK_TABLELIST A, BOK_BOOKSET B where A.BOOKSET_ID = '00000000000000000002' AND B.BOOKSET_ID != A.BOOKSET_ID and B.BOOKSET_TYPE = '01';

